t:space-between;gap:15px;font-size:12px;padding:5px 0}.cfe-summary-row dt{color:#8294ad}.cfe-summary-row dd{text-align:right;color:#27364d;max-width:70%;overflow-wrap:anywhere}.cfe-table-scroll{overflow:auto}.cfe-table-scroll table{width:100%;border-collapse:collapse;min-width:760px;font-size:11px}.cfe-table-scroll th{font-size:9px;color:#8497b3;background:#f8faff;text-align:left;text-transform:uppercase;padding:10px}.cfe-table-scroll td{padding:12px 10px;border-top:1px solid #e4eaf4}.cfe-totals{display:flex;gap:32px;flex-wrap:wrap;background:#effcf8;border:1px solid #a6e6d9;padding:13px 16px;border-radius:9px;margin-top:12px;color:#12766e}.cfe-totals small{display:block;font-size:10px;text-transform:uppercase}.cfe-totals strong{font-size:17px}.cfe-negative{color:#dc354e}.cfe-warning{width:100%;text-align:left;padding:12px;border:1px solid #f9d37b;background:#fffbeb;color:#a65516;font-size:11px;border-radius:8px;margin-bottom:12px}@media(max-width:800px){#editModal .cfe-setup,#editModal .cfe-review-panels{grid-template-columns:1fr}}
