<script>
(()=>{
 const modal=document.getElementById('editModal'),form=modal.querySelector('#editForm');let current=0,record=null;
 const editFileDocuments=@json($fileDocuments);
 const original=[...form.children].filter(el=>!el.matches('.cfe-page,input[type=hidden]'));
 const setup=form.querySelector('[data-cfe-setup]'),applicant=form.querySelector('[data-cfe-applicant]'),costs=form.querySelector('[data-cfe-costs]');
 const costNames=['client_price','vendor_id','portal_id','visa_rate','purchase_date','cost_paid_amount','cost_bank_id','payable_date'];
 costNames.forEach(name=>{const el=document.getElementById('edit_'+name);costs.append(el.closest('.cfm-grid>div'))});
 const detailGrid=original.find(el=>el.classList.contains('cfm-grid')&&el.querySelector('#edit_country_id'));
 [...detailGrid.children].forEach(el=>setup.append(el));detailGrid.remove();
 original.forEach(el=>{if(el===detailGrid)return;if(el.classList.contains('cfm-section-title')){el.remove();return}applicant.append(el)});
 const statusPanel=document.createElement('aside');statusPanel.className='cfe-panel';statusPanel.innerHTML='<h3>Status & Internal Notes</h3><div class="cfm-grid"></div>';const statusGrid=statusPanel.querySelector('.cfm-grid');['status','exception_flag'].forEach(name=>statusGrid.append(document.getElementById('edit_'+name).closest('.cfm-grid>div')));statusPanel.append(document.getElementById('edit_notes').parentElement);const setupPage=document.getElementById('cfe-page-0'),setupPanel=document.createElement('div');setupPanel.className='cfe-panel';setupPanel.append(...setupPage.children);setupPage.classList.add('cfe-setup');setupPage.append(setupPanel,statusPanel);
 const holderRow=applicant.querySelector('.cfm-file-holder-row'),fileNumberWrap=holderRow.firstElementChild,holderSelectWrap=holderRow.lastElementChild;setupPanel.append(fileNumberWrap);holderSelectWrap.hidden=true;holderRow.hidden=true;
 const primaryDetails=document.createElement('div');primaryDetails.className='cfm-grid cfe-primary-details';for(const name of ['client_type','client_id','country_id','contract_file_category_id',...(document.getElementById('edit_contract_file_visa_type_id')?['contract_file_visa_type_id']:[]),'submit_date','expected_out_date'])primaryDetails.append(document.getElementById('edit_'+name).closest('.cfm-grid>div'));const primaryNotes=document.getElementById('edit_notes').parentElement,primaryDocs=document.getElementById('edit_documents_grid'),holderInfo=applicant.querySelector('#edit_holder_info'),identityGrid=holderInfo.parentElement;identityGrid.replaceWith(holderSelectWrap,holderInfo,primaryDetails,primaryNotes);holderSelectWrap.hidden=true;const documentsHeading=document.createElement('h4');documentsHeading.className='cfe-subheading';documentsHeading.innerHTML='<i class="fas fa-file-alt"></i> Applicant Documents';primaryDocs.before(documentsHeading);document.querySelector('#cfe-page-1 [data-cfe-primary] .cfe-columns>div:first-child>h3').innerHTML='<i class="fas fa-user"></i> Applicant & File';document.querySelector('#cfe-page-1 [data-cfe-primary] .cfe-columns>div:nth-child(2)>h3').innerHTML='<i class="fas fa-clipboard-list"></i> Services & Money';
 const primaryDocAdd=document.getElementById('editAddDoc').parentElement,checklistTitle=document.createElement('h4'),primaryLinksTitle=document.createElement('h4'),primaryLinks=document.createElement('div'),primaryUploadLabel=document.createElement('label'),primaryUpload=document.createElement('input');checklistTitle.className='cfe-doc-label';checklistTitle.textContent='Required checklist';primaryLinksTitle.className='cfe-doc-label';primaryLinksTitle.textContent='Link existing documents';primaryLinks.className='cfm-doc-grid cfe-primary-links';primaryUploadLabel.className='cfe-extra-upload';primaryUploadLabel.innerHTML='<span class="cfm-lbl">Upload supporting documents</span>';primaryUpload.type='file';primaryUpload.name='primary_documents[]';primaryUpload.multiple=true;primaryUpload.accept='.pdf,.jpg,.jpeg,.png';primaryUploadLabel.append(primaryUpload);primaryDocAdd.after(primaryLinksTitle,primaryLinks,primaryUploadLabel);primaryNotes.classList.add('cfe-field');primaryNotes.querySelector('.cfm-lbl')?.classList.add('cfe-notch');
 const primaryLeft=document.querySelector('#cfe-page-1 [data-cfe-primary] .cfe-columns>div:first-child'),primaryHeading=primaryLeft.querySelector(':scope>h3'),applicantSection=document.createElement('section'),documentsSection=document.createElement('section');applicantSection.className='cfe-primary-section';documentsSection.className='cfe-primary-section';applicantSection.append(primaryHeading,applicant);documentsSection.append(documentsHeading,checklistTitle,primaryDocs,primaryDocAdd,primaryLinksTitle,primaryLinks,primaryUploadLabel);primaryLeft.classList.add('cfe-primary-left');primaryLeft.replaceChildren(applicantSection,documentsSection);
 for(const name of ['client_price','visa_rate','vendor_id','portal_id','cost_paid_amount','cost_bank_id','purchase_date','payable_date'])costs.append(document.getElementById('edit_'+name).closest('.cfm-grid>div'));
 document.getElementById('edit_vendor_id').closest('.cfm-grid>div').classList.add('cfm-full');
 document.getElementById('edit_portal_id').closest('.cfm-grid>div').classList.add('cfm-full');
 const fieldLabels={client_price:'Package charge (BDT)',visa_rate:'Processing cost (BDT)',vendor_id:'Processing vendor',purchase_date:'Cost date'};Object.entries(fieldLabels).forEach(([key,text])=>document.getElementById('edit_'+key).parentElement.querySelector('label').textContent=text);
 form.querySelectorAll('.cfm-grid>div').forEach(wrap=>{const label=wrap.querySelector(':scope>label.cfm-lbl');if(label){wrap.classList.add('cfe-field');label.classList.add('cfe-notch')}});
 const make=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el};
 const makeMoneyPanel=container=>{const bar=make('div',undefined,'cfbld-money'),breakdown=make('div',undefined,'cfbld-breakdown'),panel={bar,breakdown};container.append(bar,breakdown);return panel};
 const paintMoneyPanel=(panel,charge,processing,training=0,other=0,serviceLabel='Immigration training')=>{const cost=processing+training+other,profit=charge-cost;panel.bar.replaceChildren();for(const [title,amount] of [['Cost',cost],['Charge',charge],['Profit',profit]]){const item=make('span'),bold=make('b',cash(amount),amount<0?'loss':'');item.append(document.createTextNode(title+' '),bold);panel.bar.append(item)}panel.breakdown.replaceChildren();for(const [heading,rows] of [['Cost',[['Processing',processing],...(training?[[serviceLabel,training]]:[]),...(other?[['Others',other]]:[]),['Total cost',cost,'total']]],['Charge',[['Package',charge],['Total charge',charge,'total'],['Profit = Charge − Cost',profit,profit<0?'total loss':'total profit']]]]){const section=make('section'),title=make('h5',heading);section.append(title);for(const [label,amount,className] of rows){const row=make('p',undefined,className||''),name=make('span',label),value=make('span',cash(amount));row.append(name,value);section.append(row)}panel.breakdown.append(section)}return{cost,charge,profit}};
 const primaryMoneyPanel=makeMoneyPanel(document.querySelector('#cfe-page-1 [data-cfe-primary] .cfe-columns>div:nth-child(2)'));
 let extraSequence=0;
 const extraCards=document.getElementById('cfe-applicant-cards');
 const collapseCard=(card,collapsed)=>{card.classList.toggle('is-collapsed',collapsed);card.querySelector('[data-cfe-card-body]').hidden=collapsed;const button=card.querySelector('[data-cfe-collapse]');button.setAttribute('aria-expanded',String(!collapsed));button.querySelector('i').className='fas '+(collapsed?'fa-chevron-down':'fa-chevron-up')};
 const bindCollapse=card=>{const header=card.querySelector(':scope>header'),button=card.querySelector('[data-cfe-collapse]');button.onclick=e=>{e.stopPropagation();collapseCard(card,!card.classList.contains('is-collapsed'))};header.onclick=e=>{if(!e.target.closest('button'))collapseCard(card,!card.classList.contains('is-collapsed'))}};
 bindCollapse(extraCards.querySelector('[data-cfe-primary]'));
 const addExtraApplicant=id=>{
  if(!id||String(form.elements.passport_holder_id.value)===String(id)||extraCards.querySelector(`[data-holder-id="${id}"]`))return;
  const holder=passportHolders.find(item=>String(item.id)===String(id));if(!holder)return;
  extraCards.querySelectorAll('.cfe-applicant-card').forEach(card=>collapseCard(card,true));
  const card=document.getElementById('cfe-extra-template').content.firstElementChild.cloneNode(true),index=extraSequence++;card.dataset.holderId=id;card.dataset.index=index;
  card.querySelector('[data-cfe-name]').textContent=holder.name;card.querySelector('.cfe-card-number').textContent=String(extraCards.children.length+1);card.querySelector('[data-cfe-holder-summary]').textContent=`Passport: ${holder.passport_no||'—'} · Phone: ${holder.phone||'—'} · Nationality: ${holder.nationality||'—'}`;
  const left=card.querySelector('.cfe-columns>div'),details=make('div',undefined,'cfm-grid cfe-extra-details');
  const cleanClone=control=>{control.removeAttribute('id');control.removeAttribute('name');control.removeAttribute('tabindex');control.removeAttribute('aria-hidden');control.removeAttribute('data-select2-id');control.classList.remove('select2-hidden-accessible');control.querySelectorAll?.('[data-select2-id]').forEach(option=>option.removeAttribute('data-select2-id'));return control};
  for(const [key,title] of [['client_type','Received from'],['client_id','Agent / Client *'],['country_id','Country *'],['contract_file_category_id','Category *']]){card.querySelector(`input[data-extra="${key}"]`)?.remove();const wrap=make('div'),label=make('label',title,'cfm-lbl'),control=cleanClone(document.getElementById('edit_'+key).cloneNode(true));control.dataset.extra=key;control.classList.add('cfm-select');wrap.append(label,control);details.append(wrap)}left.querySelector('[data-cfe-documents]').before(details);
  const money=card.querySelector('.cfe-columns>div:nth-child(2) .cfm-grid');
  for(const [key,title] of [['cost_paid_amount','Processing paid amount'],['cost_bank_id','Processing bank / cash'],['purchase_date','Processing cost date'],['payable_date','Processing due date']]){const wrap=make('div'),label=make('label',title,'cfm-lbl'),control=cleanClone(document.getElementById('edit_'+key).cloneNode(true));control.dataset.extra=key;control.classList.add(control.tagName==='SELECT'?'cfm-select':'cfm-input');wrap.append(label,control);money.append(wrap)}
  const builderTemplate=document.getElementById('cfbld-card-template');
