 const initExtraPicker=()=>{if(!window.jQuery?.fn.select2)return;const picker=jQuery('#cfe-add-holder');if(!picker.hasClass('select2-hidden-accessible'))picker.select2({width:'100%',dropdownParent:jQuery(modal),placeholder:'Select passport holder...',allowClear:true});picker.off('change.cfeApplicants').on('change.cfeApplicants',()=>{const id=picker.val();if(id)addExtraApplicant(id);picker.val('').trigger('change.select2')})};document.getElementById('cfe-new-holder').onclick=()=>openCfPhModal('cfe-add-holder');
