 const totals=()=>{let cost=Math.max(0,Number(form.elements.visa_rate.value||0)-Number(record?.edit_processing_refund||0))+(record?.edit_services||[]).reduce((sum,s)=>sum+Number(s.cost),0),charge=Number(form.elements.client_price.value||0)+Number(record?.edit_charge_adjustment||0);extraCards.querySelectorAll('[data-cfe-extra]').forEach(card=>{const amount=extraAmounts(card);cost+=amount.cost;charge+=amount.charge});return{cost,charge,profit:charge-cost}};
