  const box=document.getElementById('cfe-review');box.replaceChildren();const panels=make('div',undefined,'cfe-review-panels');
  const panel=(title,entries)=>{const section=make('section',undefined,'cfe-panel');section.append(make('h3',title));const dl=make('dl');entries.forEach(([label,key])=>{const row=make('div',undefined,'cfe-summary-row');row.append(make('dt',label),make('dd',val(key)));dl.append(row)});section.append(dl);panels.append(section)};
