 modal.querySelectorAll('[data-cfe-step]').forEach((el,i)=>{el.onclick=()=>step(i);el.onkeydown=e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%3;else if(e.key==='ArrowLeft')n=(i+2)%3;else if(e.key==='Home')n=0;else if(e.key==='End')n=2;else return;e.preventDefault();step(n);modal.querySelector(`[data-cfe-step="${n}"]`).focus()}});
