 const renderPrimaryLinks=holderId=>{primaryLinks.replaceChildren();for(const doc of editFileDocuments.filter(item=>String(item.passport_holder_id)===String(holderId)&&String(item.contract_file_id)!==String(record?.id))){const label=make('label',undefined,'cfm-doc'),check=document.createElement('input'),span=make('span',doc.title||doc.original_name);check.type='checkbox';check.name='primary_linked_documents[]';check.value=doc.id;label.append(check,span);primaryLinks.append(label)}if(!primaryLinks.children.length)primaryLinks.append(make('div','No other uploaded documents for this passport holder.','cfm-doc-empty'))};
